Translate the following GNU C++11 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>

using namespace std;

using ll = long long;

const int MAX_N = 70;
const int MAX_M = 50;
const int LIM = 22;

ll binom[MAX_N + 5][MAX_N + 5];

void precompute_binomials() {
    for (int i = 0; i < MAX_N; ++i) {
        binom[i][0] = 1;
        for (int j = 1; j <= i; ++j) {
            binom[i][j] = binom[i-1][j-1] + binom[i-1][j];
        }
    }
}

int n, m, total;
int mid;
int fixed_vals[MAX_N + 5];

vector<pair<ll, int>> memo_b[MAX_M + 5][MAX_M + 5];
map<ll, ll> memo_a[MAX_M + 5][MAX_M + 5];

ll best = LLONG_MAX;
ll best_count = 0;

void update_best(ll val, ll cnt) {
    if (val < best) {
        best = val;
        best_count = cnt;
    } else if (val == best) {
        best_count += cnt;
    }
}

void dfs_b(int pos, int cnt_a, int cnt_b, ll sum = 0) {
    if (pos == mid) {
        memo_b[cnt_a][cnt_b].emplace_back(sum, 1);
        return;
    }
    for (int choice = 0; choice < 2; ++choice) {
        if (fixed_vals[pos-1] != -1 && choice != fixed_vals[pos-1]) continue;
        ll contrib = 0;
        if (choice == 0 && cnt_a > 0) {
            for (int j = 0; j < n; ++j) {
                contrib += binom[cnt_a-1][n-1] * binom[cnt_b][j] * binom[total-pos][n-j];
            }
            dfs_b(pos-1, cnt_a-1, cnt_b, sum + contrib);
        } else if (choice == 1 && cnt_b > 0) {
            for (int j = 0; j < n; ++j) {
                contrib -= binom[cnt_b-1][n-1] * binom[cnt_a][j] * binom[total-pos][n-j];
            }
            dfs_b(pos-1, cnt_a, cnt_b-1, sum + contrib);
        }
    }
}

void bfs_a() {
    for (int i = 0; i <= n+m; ++i) {
        for (int j = 0; j <= n+m; ++j) {
            memo_a[i][j].clear();
        }
    }
    memo_a[0][0][0] = 1;

    for (int i = 0; i <= n+m; ++i) {
        for (int j = 0; j <= n+m; ++j) {
            for (auto &[cur_sum, cnt] : memo_a[i][j]) {
                if (i + j == mid) {
                    auto it = lower_bound(memo_b[i][j].begin(), memo_b[i][j].end(), make_pair(-cur_sum, -1));
                    if (it != memo_b[i][j].end()) {
                        update_best(abs(cur_sum + it->first), cnt * it->second);
                    }
                    if (it != memo_b[i][j].begin()) {
                        --it;
                        update_best(abs(cur_sum + it->first), cnt * it->second);
                    }
                } else {
                    int idx = i + j;
                    for (int choice = 0; choice < 2; ++choice) {
                        if (fixed_vals[idx] != -1 && choice != fixed_vals[idx]) continue;
                        int na = i, nb = j;
                        if (choice == 0) ++na;
                        else ++nb;
                        if (na <= n+m && nb <= n+m) {
                            ll delta = 0;
                            if (choice == 0) {
                                for (int l = 0; l < n; ++l) {
                                    delta += binom[na-1][n-1] * binom[nb][l] * binom[total-idx-1][n-l];
                                }
                            } else {
                                for (int l = 0; l < n; ++l) {
                                    delta -= binom[nb-1][n-1] * binom[na][l] * binom[total-idx-1][n-l];
                                }
                            }
                            memo_a[na][nb][cur_sum + delta] += cnt;
                        }
                    }
                }
            }
        }
    }
}

void process() {
    for (int i = 0; i <= n+m; ++i) {
        for (int j = 0; j <= n+m; ++j) {
            memo_b[i][j].clear();
        }
    }
    dfs_b(total, n+m, n+m);

    for (int i = 0; i <= n+m; ++i) {
        for (int j = 0; j <= n+m; ++j) {
            sort(memo_b[i][j].begin(), memo_b[i][j].end());
            vector<pair<ll, int>> tmp;
            int sz = memo_b[i][j].size();
            for (int k = 0; k < sz; ) {
                ll val = memo_b[i][j][k].first;
                int total_cnt = 0;
                while (k < sz && memo_b[i][j][k].first == val) {
                    total_cnt += memo_b[i][j][k].second;
                    ++k;
                }
                tmp.emplace_back(val, total_cnt);
            }
            memo_b[i][j] = move(tmp);
        }
    }
    bfs_a();
}

int main() {
#ifdef matthew99
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
#endif
    precompute_binomials();
    char s[MAX_N + 5];
    scanf("%d %d %s", &n, &m, s);
    total = (n + m) * 2;
    mid = max(0, total - LIM);
    memset(fixed_vals, -1, sizeof(fixed_vals));

    process();
    best_count = 0;
    for (int i = 0; i < total; ++i) {
        if (s[i] == 'A') fixed_vals[i] = 0;
        else if (s[i] == 'B') fixed_vals[i] = 1;
    }
    process();
    cout << best_count << endl;
    return 0;
}
